const items = $input.all();
const results = [];
for (const item of items) {
  const c = item.json;
  const discountPercent = Number(c.discount_percent || 0);
  const discountValue = Number(c.discount_value || 0);
  let score = 65;
  let priority = 'NORMAL';
  if (discountPercent >= 50 || discountValue >= 100) { score = 95; priority = 'CRITICAL_BUG'; }
  else if (discountPercent >= 30 || discountValue >= 50) { score = 80; priority = 'HIGH'; }
  results.push({
    json: {
      category: 'coupon_deal',
      title: `Cupom ${c.code || 'OFERTA'}: ${discountPercent ? `${discountPercent}% OFF` : `R$ ${discountValue} OFF`} na ${c.store || 'Loja'}`,
      description: c.description || 'Cupom testado e validado em tempo real.',
      opportunity_price: discountValue > 0 ? discountValue : 0,
      original_price: 100.00,
      discount_percentage: discountPercent,
      source_name: c.store || 'Agregador de Cupons',
      source_url: c.url || 'https://exemplo.com',
      affiliate_url: c.affiliate_url || c.url,
      evaluation_score: score,
      priority
    }
  });
}
return results;
